// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListCategories List the service categories, grouped for the entry form
	// (GET /categories)
	ListCategories(ctx context.Context, request ListCategoriesRequestObject) (ListCategoriesResponseObject, error)
	// ListClients List the current user's saved clients
	// (GET /clients)
	ListClients(ctx context.Context, request ListClientsRequestObject) (ListClientsResponseObject, error)
	// CreateClient Save a new client
	// (POST /clients)
	CreateClient(ctx context.Context, request CreateClientRequestObject) (CreateClientResponseObject, error)
	// DeleteClient Delete one of the caller's clients
	// (DELETE /clients/{clientId})
	DeleteClient(ctx context.Context, request DeleteClientRequestObject) (DeleteClientResponseObject, error)
	// RenameClient Rename one of the caller's clients
	// (PATCH /clients/{clientId})
	RenameClient(ctx context.Context, request RenameClientRequestObject) (RenameClientResponseObject, error)
	// ListEntries List the caller's own entries
	// (GET /entries)
	ListEntries(ctx context.Context, request ListEntriesRequestObject) (ListEntriesResponseObject, error)
	// CreateEntry Log a new entry
	// (POST /entries)
	CreateEntry(ctx context.Context, request CreateEntryRequestObject) (CreateEntryResponseObject, error)
	// DeleteEntry Delete one of the caller's pending or rejected entries
	// (DELETE /entries/{entryId})
	DeleteEntry(ctx context.Context, request DeleteEntryRequestObject) (DeleteEntryResponseObject, error)
	// GetEntry Read one of the caller's entries
	// (GET /entries/{entryId})
	GetEntry(ctx context.Context, request GetEntryRequestObject) (GetEntryResponseObject, error)
	// UpdateEntry Replace one of the caller's pending or rejected entries
	// (PUT /entries/{entryId})
	UpdateEntry(ctx context.Context, request UpdateEntryRequestObject) (UpdateEntryResponseObject, error)
	// GetHealth Report that the API is up and which build is running
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetMe Read the current user's profile and effective roles
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

